1	package auth
2	
3	import (
4		"fmt"
5	
6		"github.com/entireio/auth-go/tokens"
7		"github.com/entireio/cli/internal/entireclient/contexts"
8		"github.com/entireio/cli/internal/entireclient/tokenstore"
9	)
10	
11	// CurrentContextToken returns the login JWT for the active context in
12	// contexts.json, or ("", false) when there is no current context or it
13	// has no stored token. This is the contexts.json half of the CLI's
14	// credential resolution; callers fall back to the legacy keyring entry so
15	// pre-contexts logins keep working until migrated.
16	func CurrentContextToken() (string, bool) {
17		f, err := contexts.Load(contexts.DefaultConfigDir())
18		if err != nil {
19			return "", false
20		}
21		c := f.Find(f.CurrentContext)
22		if c == nil {
23			return "", false
24		}
25		tok, err := LoginTokenForContext(c)
26		if err != nil || tok == "" {
27			return "", false
28		}
29		return tok, true
30	}
31	
32	// RemoveCurrentContext deletes the active context from contexts.json and
33	// its keyring token, advancing current_context to whatever remains. It is
34	// a no-op (returns nil) when there is no current context. Used by logout.
35	func RemoveCurrentContext() error {
36		// Read-modify-write in a single locked Modify so the context we delete
37		// is exactly the one we capture the keychain slot from (separate Load +
38		// Modify would race a concurrent `auth use`).
39		var svc, handle string
40		if err := contexts.Modify(contexts.DefaultConfigDir(), func(f *contexts.File) (bool, error) {
41			current := f.Find(f.CurrentContext)
42			if current == nil {
43				return false, nil
44			}
45			svc, handle = current.KeychainService, current.Handle
46			f.Delete(current.Name)
47			// Delete advances current_context to a surviving context; for logout
48			// that would silently re-authenticate as another account. Leave no
49			// active context — logged out means logged out.
50			f.CurrentContext = ""
