package auth

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"

	"entire.io/client/clusterdiscovery"
	"entire.io/client/contexts"
)

// ResolveContext picks the auth context for an entire-server cluster.
// Honors an explicit cluster_contexts[host] binding when present, and
// otherwise hits the cluster's /.well-known/entire-cluster.json to
// discover its trusted issuers and match against local contexts
// (auto-binding the first match for next time). Returns the bits the
// rest of the proxy needs:
//
//   - coreURL: the entire-core URL to hit for STS exchanges (the JWT
//     issuer recorded at login time);
//   - contextName: used to write a cluster→context binding after the
//     first successful STS exchange (auto-bind on success);
//   - keychainService + handle: the OS keyring slot the access and
//     refresh tokens live under, for GetTokenWithRefresh.
//
// Errors when discovery surfaces no usable local context — the
// returned message includes the cluster's advertised login URLs so
// the operator knows which `--base-url` to login against.
//
// No current_context fallback: a binding-less host could otherwise
// silently reuse a staging login against a prod cluster (or vice
// versa). The cluster's own /.well-known is the authoritative answer
// to "which env am I in".
func ResolveContext(ctx context.Context, httpClient *http.Client, configDir, clusterHost string, debugf clusterdiscovery.DebugFunc) (coreURL, contextName, keychainService, handle string, err error) {
	c, resolveErr := clusterdiscovery.ResolveContextForCluster(ctx, configDir, clusterHost, httpClient, debugf)
	if resolveErr != nil {
		return "", "", "", "", fmt.Errorf("resolve context for cluster %s: %w", clusterHost, resolveErr)
	}
	return strings.TrimRight(c.CoreURL, "/"), c.Name, c.KeychainService, c.Handle, nil
}

// CoreURLFromEnvToken extracts the home-region URL from an
// ENTIRE_TOKEN-supplied JWT's aud claim. The CI/automation flow uses
// this when there's no contexts.json on disk: the bearer is in env,
// and login / SA-session JWTs both carry aud=<homeRegionBaseURL> (see
// core/authn/jwt.go), so STS routes correctly even cross-region.
//
// We read aud, not iss: login and sa-session JWTs both carry
// aud=<homeRegionBaseURL>, which is the contract STS routing already
// depends on. iss is also a URL (cfg.AuthBaseURL) but isn't part of
// that contract — for cross-region tokens it's the issuing region's
// auth origin, which may or may not equal the home-region URL.
//
// No signature verification at this layer: STS itself rejects forged
// tokens, and the cluster rejects anything STS happily issues if the
// audience doesn't match.
func CoreURLFromEnvToken(token string) (string, error) {
	auds := jwtAudiences(token)
	for _, a := range auds {
		if strings.HasPrefix(a, "http://") || strings.HasPrefix(a, "https://") {
			return strings.TrimRight(a, "/"), nil
		}
	}
	return "", errors.New("ENTIRE_TOKEN has no URL-shaped aud claim — must be a login or sa-session JWT whose aud is the home-region URL; ops/repo-scoped JWTs (aud=service:entiredb) aren't usable here. Run `entire-core auth login` or use workload-identity to mint one")
}

// jwtAudiences returns the aud claim from a JWT's payload as a list,
// handling both the string and array JSON forms (RFC 7519 allows
// either). Returns nil when the token isn't a parseable three-segment
// JWT or the claim is absent.
func jwtAudiences(token string) []string {
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return nil
	}
	payload, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return nil
	}
	var raw struct {
		Aud json.RawMessage `json:"aud"`
	}
	if err := json.Unmarshal(payload, &raw); err != nil || len(raw.Aud) == 0 {
		return nil
	}
	var single string
	if err := json.Unmarshal(raw.Aud, &single); err == nil {
		return []string{single}
	}
	var multi []string
	if err := json.Unmarshal(raw.Aud, &multi); err == nil {
		return multi
	}
	return nil
}

// DefaultConfigDir is $ENTIRE_CONFIG_DIR if set, else ~/.config/entire.
// Thin alias so callers don't have to import client/contexts directly.
func DefaultConfigDir() string {
	return contexts.DefaultConfigDir()
}
