############ client/clusterdiscovery/resolve.go ############
package clusterdiscovery

import (
	"context"
	"errors"
	"fmt"
	"net/http"

	"entire.io/client/contexts"
)

// ResolveContextForCluster picks the auth context for clusterHost.
// Resolution order:
//
//  1. Explicit `cluster_contexts[clusterHost]` binding in contexts.json
//     pointing at an existing context — used as-is.
//  2. Discovery via /.well-known/entire-cluster.json on the cluster
//     itself, matched against existing local contexts by the
//     advertised core_urls. The first advertised URL with a local
//     context wins, and the cluster→context binding is written so the
//     next call skips discovery.
//  3. No local context matches any advertised URL — return a
//     fatal-ready error with the login hint listing the cluster's
//     advertised issuers.
//
// We deliberately do NOT fall back to current_context for an unknown
// cluster host. The old fallback would silently use a staging
// context against a prod (entire.io) cluster — which
// then 400s as "unknown cluster_host" because the cluster's own
// registry doesn't know the host. The cluster's /.well-known is the
// authoritative answer to "which env am I in", so we ask it.
//
// debugf is optional; nil suppresses debug output.
func ResolveContextForCluster(ctx context.Context, configDir, clusterHost string, httpClient *http.Client, debugf DebugFunc) (*contexts.Context, error) {
	if debugf == nil {
		debugf = func(string, ...any) {}
	}
	f, err := contexts.Load(configDir)
	if err != nil {
		return nil, fmt.Errorf("load contexts: %w", err)
	}
	if name, ok := f.ClusterContexts[clusterHost]; ok && name != "" {
		if c := f.Find(name); c != nil {
			debugf("contexts.json binding %s -> %s", clusterHost, c.Name)
			return c, nil
		}
		debugf("stale binding %s -> %q (context no longer exists); falling through to discovery", clusterHost, name)
	}
	body, err := Discover(ctx, clusterHost, httpClient, debugf)
	if err != nil {
		return nil, formatDiscoveryError(clusterHost, err)
	}
	for _, coreURL := range body.CoreURLs {
		matches := f.ContextsForIssuer(coreURL)
		if len(matches) == 0 {
			continue
		}
		c := matches[0]
		if bindErr := contexts.BindCluster(configDir, clusterHost, c.Name); bindErr != nil {
			// Non-fatal: we still resolved a usable context. Next
			// invocation will pay the discovery round-trip again.
			debugf("auto-bind %s -> %s failed: %v", clusterHost, c.Name, bindErr)
		} else {
			debugf("auto-bound %s -> %s after discovery match on %s", clusterHost, c.Name, coreURL)
		}
		return c, nil
	}
	return nil, errors.New(RenderLoginHint(clusterHost, body.CoreURLs))
}

// formatDiscoveryError turns a Discover error into the message
// operators have always seen at this layer. Kept here (not on the
// sentinels themselves) so the package's errors stay machine-readable
// while the caller-facing strings remain centralised.
func formatDiscoveryError(clusterHost string, err error) error {
	switch {
	case errors.Is(err, ErrUnreachable):
		return fmt.Errorf("%s doesn't look like a cluster, or it is unreachable: %w", clusterHost, err)
	case errors.Is(err, ErrNoIssuers):
		return fmt.Errorf("cluster %s does not advertise any trusted login servers (HTTP 503 from %s); contact the cluster administrator",
			clusterHost, Path)
	case errors.Is(err, ErrNoCoreURLs):
		return fmt.Errorf("cluster %s advertises no trusted core URLs (empty list at %s); contact the cluster administrator",
			clusterHost, Path)
	default:
		return fmt.Errorf("cluster discovery for %s: %w", clusterHost, err)
	}
}

############ internal/remotehelper/entire/auth/scoped.go ############
// Package auth exchanges a login JWT for repo-scoped tokens via
// entire-core's RFC 8693 token endpoint and classifies outbound git
// smart-HTTP requests so the right scope can be requested. It also
// owns the contexts.json / ENTIRE_TOKEN context-resolution flow.
//
// The exchange machinery itself lives in entire.io/client/repocreds;
// this package adds the git-remote-entire-specific bits: a baked-in
// repoPath (since each helper instance talks to one repo), the
// pull/push classifier, and an onFirstSuccess hook used to auto-bind
// the cluster→context mapping only after authentication has proven
// itself.
package auth

import (
	"context"
	"fmt"
	"net/http"
	"strings"
	"sync"

	"entire.io/client/repocreds"
	"entire.io/internal/remotehelper/debuglog"
)

// ScopedAuth exchanges a login JWT for repo-scoped tokens and caches
// them. Concurrency-safe via repocreds.Cache.
type ScopedAuth struct {
	cache    *repocreds.Cache
	repoPath string

	// onFirstSuccess fires exactly once after the first successful STS
	// exchange. Used to write the cluster→context binding to
	// contexts.json only after we've proven the chosen context can
	// authenticate against this cluster — never speculatively.
	onFirstSuccess func()
	firstSuccess   sync.Once
}

// NewScoped constructs a ScopedAuth for the given core endpoint and
// login JWT. The repoPath is normalized (trailing slash stripped) so
// that the audience matches the receiver's recorded URL exactly.
// onFirstSuccess may be nil.
func NewScoped(coreURL, loginJWT, repoPath, clusterURL string, httpClient *http.Client, onFirstSuccess func()) *ScopedAuth {
	provider := func(context.Context) (string, error) { return loginJWT, nil }
	return &ScopedAuth{
		cache:          repocreds.New(coreURL, clusterURL, provider, httpClient),
		repoPath:       strings.TrimRight(repoPath, "/"),
		onFirstSuccess: onFirstSuccess,
	}
}

// Get returns a valid scoped token for the given action, exchanging
// against core if no cached entry exists or the cached one has crossed
// the safety margin. The audience is clusterURL + repoPath, matching
// what the receiving route compares against — audience IS the resource
// check (RFC 8707).
//
// The "auto-bind never speculative" guarantee relies on this instance
// having a freshly-constructed (empty) cache: the first Get is always
// a cache miss → real exchange. If a future change shares or
// pre-populates the cache across instances, the first Get could be a
// cache HIT and onFirstSuccess would fire without this invocation
// having proven its credentials — re-gate here on a real exchange if
// that happens.
func (s *ScopedAuth) Get(ctx context.Context, action string) (string, error) {
	debuglog.Printf("requesting scoped token for action=%s repo=%s", action, s.repoPath)
	token, err := s.cache.Token(ctx, s.repoPath, action)
	if err != nil {
		return "", fmt.Errorf("mint scoped JWT: %w", err)
	}
	if s.onFirstSuccess != nil {
		s.firstSuccess.Do(s.onFirstSuccess)
	}
	return token, nil
}

// GitActionFromRequest classifies an outbound git smart-HTTP request
// as "pull", "push", or "" (unclassified). Mirrors the server's gitOp
// helper; if an endpoint can't be classified, there's no meaningful
// scoped token to issue.
func GitActionFromRequest(req *http.Request) string {
	path := req.URL.Path
	switch req.Method {
	case http.MethodPost:
		switch {
		case strings.HasSuffix(path, "/git-receive-pack"):
			return "push"
		case strings.HasSuffix(path, "/git-upload-pack"):
			return "pull"
		}
	case http.MethodGet:
		if strings.HasSuffix(path, "/info/refs") {
			switch req.URL.Query().Get("service") {
			case "git-receive-pack":
				return "push"
			case "git-upload-pack":
				return "pull"
			}
		}
	}
	return ""
}
